<script lang="ts">
import {base} from '$app/paths';
import {onMount} from 'svelte';import {Chess,type Square,type Move} from 'chess.js';import {Settings,RotateCcw,Volume2,FlaskConical} from 'lucide-svelte';import {Engine} from '$lib/engine';import {characters,dialogue,outcome,type Mood} from '$lib/game';import {sound} from '$lib/audio';import Cutscene from '$lib/Cutscene.svelte';import './style.css';
let game=new Chess(),fen=game.fen(),moves:Move[]=[],selected:Square|null=null,legal:string[]=[],side='w',level='Normal',busy=false,error='',result='',settings=false,lab=false,effects=true,muted=false,volume=.35,labChar=0,speed=1,promotion:{from:Square,to:Square}|null=null,cut:Cutscene,engine:Engine,epoch=0,playing=false;
$: board=new Chess(fen).board();$: last=moves.at(-1);$: squares=side==='w'?board.flat():board.flat().reverse();$: moodPlayer=(result?(result.includes(side==='w'?'백 승리':'흑 승리')?'Victory':'Defeat'):game.isCheck()&&game.turn()===side?'Worried':last?.captured&&last.color===side?'Happy':'Idle') as Mood;
$: moodAi=(result?(moodPlayer==='Victory'?'Defeat':'Victory'):game.isCheck()&&game.turn()!==side?'Worried':last?.captured&&last.color===side?'Surprised':'Idle') as Mood;
const glyph:Record<string,string>={wk:'♔',wq:'♕',wr:'♖',wb:'♗',wn:'♘',wp:'♙',bk:'♚',bq:'♛',br:'♜',bb:'♝',bn:'♞',bp:'♟'};
function sync(){fen=game.fen();moves=game.history({verbose:true});result=outcome(game);selected=null;legal=[];localStorage.setItem('anime-chess',JSON.stringify({pgn:game.pgn(),side,level,effects,muted,volume}))}
function boot(){engine?.destroy();engine=new Engine(s=>{error=s;busy=false})}
onMount(()=>{try{const s=JSON.parse(localStorage.getItem('anime-chess')||'null');if(s){game.loadPgn(s.pgn);side=s.side;level=s.level;effects=s.effects;muted=s.muted;volume=s.volume}}catch{error='저장한 대국을 복원할 수 없습니다.'}sync();boot();void ai();return()=>engine?.destroy()});
async function cinematic(type:string,who:number){if(!effects)return;playing=true;try{await cut.play(type,who,speed)}finally{playing=false}}
async function commit(from:Square,to:Square,p='q'){let m:Move;try{m=game.move({from,to,promotion:p})}catch{return}sync();sound.play(m.captured?'capture':'move');const who=m.color===side?0:1;if(result){if(game.isCheckmate())await cinematic('Checkmate',who);sound.play('victory')}else if(m.promotion)await cinematic('Promotion',who);else if(m.captured==='q')await cinematic('Queen Capture',who);else if(game.isCheck())await cinematic('Check',who)}
async function ai(){if(game.turn()===side||game.isGameOver()||error)return;const id=epoch;busy=true;try{const best=await engine.move(game.fen(),level);if(id!==epoch||!best)return;await commit(best.slice(0,2) as Square,best.slice(2,4) as Square,best[4]||'q')}catch(e){error='AI 계산 실패: '+String(e)}finally{if(id===epoch)busy=false}}
async function choose(s:Square){sound.unlock();sound.muted=muted;sound.volume=volume;if(busy||playing||result||error||promotion||game.turn()!==side)return;if(selected&&legal.includes(s)){const opts=game.moves({square:selected,verbose:true}).filter(m=>m.to===s);if(opts.some(m=>m.promotion)){promotion={from:selected,to:s};return}await commit(selected,s);await ai();return}if(game.get(s)?.color===side){selected=s;legal=game.moves({square:s,verbose:true}).map(m=>m.to)}else{selected=null;legal=[]}}
function restart(){epoch++;cut?.skip();playing=false;busy=false;error='';promotion=null;game=new Chess();sync();boot();void ai()}
function undo(){if(playing)return;epoch++;busy=false;promotion=null;game.undo();if(game.turn()!==side&&game.history().length)game.undo();sync();boot();void ai()}
function square(i:number):Square{const n=side==='w'?i:63-i;return ('abcdefgh'[n%8]+(8-Math.floor(n/8))) as Square}
async function preview(k:string){sound.unlock();await cinematic(k,labChar)}
</script>
<svelte:head><title>Astral Gambit — Anime Chess</title><meta name="description" content="A cinematic chess duel beneath the stars"/></svelte:head>
<div class="app"><header><a href={base+"/"} class="brand">✧ <span>ASTRAL GAMBIT<small>星の一手 · ANIME CHESS</small></span></a><div class="header-right"><span class="live">● SINGLE PLAYER</span><button aria-label="사운드" onclick={()=>{muted=!muted;sound.muted=muted;sync()}}><Volume2 size={18}/></button><button aria-label="설정" onclick={()=>settings=!settings}><Settings size={18}/></button></div></header>
<div class="chapter"><span>CHAPTER 01 / THE CELESTIAL DUEL</span><h1>Every move tells a story.</h1><p>별빛 아래, 당신만의 한 수를.</p></div>
<main><aside class="character player" data-mood={moodPlayer}><div class="rank">✦ YOUR CHAMPION</div><img src={base+characters[0].art} alt="은발의 기사 아리아"/><div class="character-info"><small>THE ASTRAL KNIGHT</small><h2>Aria <span>アリア</span></h2><p class="speech">“{dialogue[moodPlayer]}”</p><div class="badge">{side==='w'?'♔ WHITE':'♚ BLACK'} <span>{moodPlayer}</span></div></div></aside>
<section class="arena"><div class="board-heading"><span>✧ CELESTIAL COURT</span><span>{busy?'AI THINKING…':result|| (game.turn()===side?'YOUR TURN':'REINA’S TURN')}</span></div><div class="board-frame"><div class="board">{#each squares as piece,i}{@const sq=square(i)}<button class:dark={(Math.floor(i/8)+i%8)%2===1} class:selected={selected===sq} class:last={last?.from===sq||last?.to===sq} class:check={piece?.type==='k'&&piece.color===game.turn()&&game.isCheck()} class="square" aria-label={`${sq} ${piece?piece.color+piece.type:'empty'}`} draggable={piece?.color===side&&!busy&&!playing} ondragstart={()=>{selected=sq;legal=game.moves({square:sq,verbose:true}).map(m=>m.to)}} ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();void choose(sq)}} onclick={()=>choose(sq)}><span class:white-piece={piece?.color==='w'} class="piece">{piece?glyph[piece.color+piece.type]:''}</span>{#if legal.includes(sq)}<i class="dot"></i>{/if}{#if i%8===0}<small class="coord rankcoord">{sq[1]}</small>{/if}{#if i>=56}<small class="coord filecoord">{sq[0]}</small>{/if}</button>{/each}</div></div><div class="board-footer"><span>● {error?'ENGINE ERROR':'STOCKFISH 17.1 / WASM'}</span><span>{moves.length} PLY · {level.toUpperCase()}</span></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if result&&!playing}<div class="result"><h2>{result}</h2><button onclick={restart}>새로운 대국 →</button></div>{/if}</section>
<aside class="character opponent" data-mood={moodAi}><div class="rank">✦ YOUR OPPONENT</div><img src={base+characters[1].art} alt="흑발의 전략가 레이나"/><div class="character-info"><small>THE CRIMSON STRATEGIST</small><h2>Reina <span>レイナ</span></h2><p class="speech">“{dialogue[moodAi]}”</p><div class="badge">{side==='w'?'♚ BLACK':'♔ WHITE'} <span>{moodAi}</span></div></div></aside></main>
<footer><div class="history"><small>MOVE CHRONICLE</small><div>{#if !moves.length}<span class="empty">첫 번째 수로 이야기를 시작하세요.</span>{/if}{#each moves as m,i}<span>{i%2===0?Math.floor(i/2)+1+'. ':''}{m.san}</span>{/each}</div></div><div class="controls"><button onclick={undo} disabled={!moves.length||playing}><RotateCcw size={16}/> 무르기</button><button onclick={restart}>새 대국</button><select aria-label="AI 난이도" bind:value={level} onchange={sync}><option>Easy</option><option>Normal</option><option>Hard</option></select><button class="lab-button" onclick={()=>lab=!lab}><FlaskConical size={16}/> Cutscene Lab</button></div></footer><div class="bottom">A DUEL OF MINDS. A MOMENT OF MAGIC. <span>PROTOTYPE / 01</span></div></div>
{#if settings||lab}<div class="modal-backdrop"><section class="panel"><button class="close" onclick={()=>{settings=false;lab=false}}>✕</button><small>ASTRAL GAMBIT</small><h2>{lab?'Cutscene Lab':'대국 설정'}</h2>{#if lab}<label>캐릭터 <select bind:value={labChar}><option value={0}>Aria</option><option value={1}>Reina</option></select></label><label>재생 속도 <input type="range" min="0.5" max="2" step="0.25" bind:value={speed}/>{speed}×</label><div class="lab-grid">{#each ['Check','Queen Capture','Promotion','Checkmate','Victory','Defeat'] as k}<button disabled={playing||busy} onclick={()=>preview(k)}>Play {k}</button>{/each}</div><p>실제 대국과 동일한 컷씬 타임라인을 재생합니다.</p>{:else}<label>플레이 색상 <select bind:value={side} onchange={restart}><option value="w">백색 · 먼저 두기</option><option value="b">흑색 · 나중에 두기</option></select></label><label><input type="checkbox" bind:checked={effects} onchange={sync}/> 시네마틱 연출</label><label><input type="checkbox" bind:checked={muted} onchange={()=>{sound.muted=muted;sync()}}/> 음소거</label><label>볼륨 <input type="range" min="0" max="1" step="0.05" bind:value={volume} onchange={()=>{sound.volume=volume;sync()}}/></label>{/if}</section></div>{/if}
{#if promotion}<div class="modal-backdrop"><section class="panel"><h2>승격할 기물을 선택하세요</h2><div class="promotions">{#each ['q','r','b','n'] as p}<button onclick={async()=>{const m=promotion!;promotion=null;await commit(m.from,m.to,p);await ai()}}>{glyph[side+p]}</button>{/each}</div></section></div>{/if}<Cutscene bind:this={cut}/>
